<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {appLock} from '../services/appLock'
import {installAppLockLifecycle} from '../services/appLockLifecycle'
import {isDesktopClient} from '../services/serverConfig'
const locked=appLock.locked,secret=ref(''),newPin=ref(''),confirmation=ref(''),recovery=ref(false),busy=ref(false),error=ref(''),input=ref<HTMLInputElement>()
let cleanup:(()=>void)|undefined,unlisten:(()=>void)|undefined,disposed=false
onMounted(()=>{cleanup=installAppLockLifecycle();if(isDesktopClient())void import('@tauri-apps/api/window').then(async({getCurrentWindow})=>{const stop=await getCurrentWindow().onFocusChanged(event=>{if(!event.payload&&appLock.config.value?.lockOnBackground)appLock.lock()});if(disposed)stop();else unlisten=stop}).catch(()=>{})})
onBeforeUnmount(()=>{disposed=true;cleanup?.();unlisten?.()})
watch(locked,async value=>{secret.value='';newPin.value='';confirmation.value='';error.value='';recovery.value=false;if(value){await nextTick();input.value?.focus()}},{immediate:true})
async function unlock(){busy.value=true;error.value='';try{if(recovery.value){if(newPin.value!==confirmation.value)throw Error('两次新 PIN 不一致');await appLock.changePin(secret.value,newPin.value,true);await appLock.unlock(newPin.value)}else await appLock.unlock(secret.value)}catch(source){error.value=source instanceof Error?source.message:'解锁失败';secret.value='';await nextTick();input.value?.focus()}finally{busy.value=false}}
function switchRecovery(){recovery.value=!recovery.value;secret.value='';newPin.value='';confirmation.value='';error.value='';void nextTick(()=>input.value?.focus())}
</script>
<template>
 <Teleport to="body"><section v-if="locked" data-app-lock-screen class="app-lock-screen" role="dialog" aria-modal="true" aria-labelledby="app-lock-title"><form @submit.prevent="unlock"><img src="/ji-yu-icon.png" alt=""><h1 id="app-lock-title">迹语已锁定</h1><p>{{recovery?'使用恢复码重新设置 PIN，然后解锁。':'输入本机 PIN，继续使用。'}}</p><label>{{recovery?'恢复码':'PIN'}}<input ref="input" v-model="secret" type="password" :inputmode="recovery?'text':'numeric'" :maxlength="recovery?128:12" autocomplete="off" :disabled="busy" autofocus></label><template v-if="recovery"><label>新 PIN<input v-model="newPin" type="password" inputmode="numeric" maxlength="12" autocomplete="new-password" :disabled="busy"></label><label>确认新 PIN<input v-model="confirmation" type="password" inputmode="numeric" maxlength="12" autocomplete="new-password" :disabled="busy"></label></template><p v-if="error" role="alert" class="app-lock-error">{{error}}</p><button type="submit" class="app-lock-submit" :disabled="busy||!secret||(recovery&&(!newPin||!confirmation))">{{busy?'正在校验…':recovery?'重设 PIN 并解锁':'解锁软件'}}</button><button type="button" class="app-lock-recover" :disabled="busy" @click="switchRecovery">{{recovery?'返回 PIN 解锁':'忘记 PIN？使用恢复码'}}</button></form></section></Teleport>
</template>
<style scoped>
.app-lock-screen{position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;padding:24px;box-sizing:border-box;overflow:auto;background:#f5f8f6;color:#233d31}.app-lock-screen form{box-sizing:border-box;width:min(360px,100%);padding:30px;border:1px solid #dfe7e3;border-radius:18px;background:#fff;box-shadow:0 14px 50px #173c2b12}.app-lock-screen img{display:block;width:44px;height:44px;margin:0 auto 18px;border-radius:12px}.app-lock-screen h1{font-size:21px;text-align:center;margin:0 0 12px}.app-lock-screen p{font-size:13px;line-height:1.6;color:#74857c;text-align:center}.app-lock-screen label{display:grid;gap:7px;font-size:12px;margin-top:16px}.app-lock-screen input{width:100%;box-sizing:border-box;border:1px solid #dfe7e3;border-radius:8px;padding:12px;font:inherit;font-size:17px;letter-spacing:2px}.app-lock-screen input:focus{outline:2px solid #89b9a9;outline-offset:2px}.app-lock-screen button{width:100%;padding:11px;border-radius:8px;cursor:pointer}.app-lock-submit{margin-top:20px;background:#137354;color:#fff;border:0}.app-lock-recover{margin-top:10px;background:transparent;border:0;color:#74857c;font-size:12px}.app-lock-screen button:disabled{opacity:.5;cursor:not-allowed}.app-lock-screen .app-lock-error{color:#b42318}
</style>
